import { usePrefix } from "../../internal/usePrefix.js";
import { ArrowDown, ArrowUp } from "../../internal/keyboard/keys.js";
import { match } from "../../internal/keyboard/match.js";
import { AriaLabelPropType } from "../../prop-types/AriaPropTypes.js";
import Link from "./Link.js";
import { forwardRef } from "react";
import cx from "classnames";
import PropTypes from "prop-types";
import { jsx } from "react/jsx-runtime";
//#region src/components/UIShell/SwitcherItem.tsx
/**
* Copyright IBM Corp. 2023, 2025
*
* This source code is licensed under the Apache-2.0 license found in the
* LICENSE file in the root directory of this source tree.
*/
const SwitcherItem = forwardRef((props, forwardRef) => {
	const { "aria-label": ariaLabel, "aria-labelledby": ariaLabelledBy, className: customClassName, children, isSelected, expanded, tabIndex = expanded ? 0 : -1, index, handleSwitcherItemFocus, onKeyDown = () => {}, href, target, rel, ...rest } = props;
	const prefix = usePrefix();
	const classNames = cx(`${prefix}--switcher__item`, { [customClassName || ""]: !!customClassName });
	const accessibilityLabel = {
		"aria-label": ariaLabel,
		"aria-labelledby": ariaLabelledBy
	};
	const linkClassName = cx(`${prefix}--switcher__item-link`, { [`${prefix}--switcher__item-link--selected`]: isSelected });
	function setTabFocus(evt) {
		if (match(evt, ArrowDown)) {
			evt.preventDefault();
			handleSwitcherItemFocus?.({
				currentIndex: index || -1,
				direction: 1
			});
		}
		if (match(evt, ArrowUp)) {
			evt.preventDefault();
			handleSwitcherItemFocus?.({
				currentIndex: index || -1,
				direction: -1
			});
		}
	}
